<?php
if (!defined('ABSPATH')) exit;
final class GDCP_Calendar_Service {
 public function custom_events($start,$end,$project_id=0){$tenant=gd_client_portal_is_platform_admin()?0:absint(gd_client_portal_get_current_tenant_id());if(!$tenant&&!gd_client_portal_is_platform_admin())return array();$rows=gdcp_calendar_repository()->events($start,$end,$project_id,$tenant);return array_values(array_filter($rows,function($e){$p=gd_client_portal_get_project_by_id($e->project_id);return gd_client_portal_calendar_project_visible($p);}));}
 public function add($project_id,$title,$start_at,$end_at='',$description='',$user_id=0){$p=gd_client_portal_get_project_by_id($project_id);if(!gd_client_portal_calendar_project_visible($p)||!(current_user_can('manage_options')||gd_client_portal_user_is_tenant_admin()))return false;$title=sanitize_text_field($title);$start=sanitize_text_field($start_at);$end=$end_at?sanitize_text_field($end_at):null;if(!$title||!strtotime($start))return false;$user_id=absint($user_id);if($user_id&&gd_client_portal_cached_user($user_id)){if(absint(get_user_meta($user_id,'gd_client_portal_tenant_id',true))!==absint($p->tenant_id))$user_id=0;}else $user_id=0;$id=gdcp_calendar_repository()->insert(array('project_id'=>$p->id,'tenant_id'=>$p->tenant_id,'user_id'=>$user_id,'event_type'=>'milestone','title'=>$title,'description'=>sanitize_textarea_field($description),'start_at'=>$start,'end_at'=>$end,'status'=>'scheduled','created_by'=>gd_client_portal_cached_current_user_id()));if($id&&function_exists('gd_client_portal_create_notification'))gd_client_portal_create_notification($p->user_id,__('New project milestone scheduled','gd-client-portal'),sprintf(__('“%s” was added to project “%s”.','gd-client-portal'),$title,$p->title),'calendar_milestone',$p->id,$p->tenant_id);if($id)do_action('gd_client_portal_project_milestone_created',$p->id,$title,$id);return $id;}
 public function delete($id){if(!$id||!(current_user_can('manage_options')||gd_client_portal_user_is_tenant_admin()))return false;$event=gdcp_calendar_repository()->find($id);if(!$event)return false;$p=gd_client_portal_get_project_by_id($event->project_id);if(!gd_client_portal_calendar_project_visible($p))return false;if(gdcp_calendar_repository()->delete($id)){do_action('gd_client_portal_project_milestone_deleted',$event->project_id,$event->title,$id);return true;}return false;}
}
function gdcp_calendar_service(){static $s;if(!$s)$s=new GDCP_Calendar_Service();return $s;}
